int write_register_set(struct task_struct *child, addr_t addr, addr_t data) {
    if (!child || addr == 0) {
        return -EINVAL;
    }

    addr_t offset = addr & 0xFFF;

    if (offset <= 0x100) {
        /* psw */
        if (offset != 0) {
            return -EINVAL;
        }
        if (data & 0xFF00000000000000) {
            return -EINVAL;
        }
        child->thread.psw = data;
    } else if (offset <= 0x200) {
        /* gpr */
        int gpr_index = (offset - 0x100) / sizeof(addr_t);
        if (gpr_index < 0 || gpr_index >= 16) {
            return -EINVAL;
        }
        child->thread.gpr[gpr_index] = data;
    } else if (offset <= 0x300) {
        /* acrs */
        int acr_index = (offset - 0x200) / sizeof(addr_t);
        if (acr_index < 0 || acr_index >= 16) {
            return -EINVAL;
        }
        child->thread.acr[acr_index] = data;
    } else if (offset <= 0x400) {
        /* floating point registers */
        int fpr_index = (offset - 0x300) / sizeof(addr_t);
        if (fpr_index < 0 || fpr_index >= 16) {
            return -EINVAL;
        }
        child->thread.fpr[fpr_index] = data;
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_register_set(struct task_struct *child, addr_t addr, addr_t data)
{
    if (!child || addr >= REGISTER_SET_SIZE)
        return -EINVAL;

    switch (addr) {
        case PSW_ADDRESS:
            if (data & ~(PSW_VALID_MASK))
                return -EINVAL;
            child->regs.psw = data;
            break;
        case GPR0_ADDRESS ... GPR15_ADDRESS:
            int reg_index = addr - GPR0_ADDRESS;
            if (reg_index >= GPR_COUNT)
                return -EINVAL;
            child->regs.gpr[reg_index] = data;
            break;
        case ACR0_ADDRESS ... ACR15_ADDRESS:
            reg_index = addr - ACR0_ADDRESS;
            if (reg_index >= ACR_COUNT)
                return -EINVAL;
            child->regs.acrs[reg_index] = data;
            break;
        case FPR0_ADDRESS ... FPR31_ADDRESS:
            reg_index = addr - FPR0_ADDRESS;
            if (reg_index >= FPR_COUNT)
                return -EINVAL;
            child->regs.fprs[reg_index] = data;
            break;
        default:
            if (!handle_special_register(child, addr, data))
                return -EINVAL;
            break;
    }

    return 0;
}

int write_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (!child || addr >= TASK_REGS_SIZE) {
        return -EINVAL;
    }

    if (addr >= PSW_OFFSET && addr < (PSW_OFFSET + sizeof(psw_t))) {
        psw_t *psw = (psw_t *)((char *)child->regs + addr);
        if (data & ~(PSW_VALID_MASK)) {
            return -EINVAL;
        }
        *psw = data;
    } else if (addr >= GPR_OFFSET && addr < (GPR_OFFSET + GPR_SIZE)) {
        unsigned int reg_index = (addr - GPR_OFFSET) / sizeof(addr_t);
        if (reg_index >= MAX_GPRS) {
            return -EINVAL;
        }
        ((addr_t *)((char *)child->regs + GPR_OFFSET))[reg_index] = data;
    } else if (addr >= ACR_OFFSET && addr < (ACR_OFFSET + ACR_SIZE)) {
        unsigned int acr_index = (addr - ACR_OFFSET) / sizeof(acr_t);
        if (acr_index >= MAX_ACRS) {
            return -EINVAL;
        }
        ((acr_t *)((char *)child->regs + ACR_OFFSET))[acr_index] = data & ACR_MASK;
    } else if (addr >= FPR_OFFSET && addr < (FPR_OFFSET + FPR_SIZE)) {
        unsigned int fpr_index = (addr - FPR_OFFSET) / sizeof(fpr_t);
        if (fpr_index >= MAX_FPRS) {
            return -EINVAL;
        }
        ((fpr_t *)((char *)child->regs + FPR_OFFSET))[fpr_index] = *(fpr_t *)&data;
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_register_set(struct task_struct *child, addr_t addr, addr_t data) {
    if (!child || (addr & 0x3))
        return -EINVAL;

    switch (addr) {
        case PSW_REGISTER:
            if (data & ~(PSW_MASK)) {
                return -EINVAL;
            }
            child->thread.psw = data;
            break;
        case GPR_REGISTER_BASE ... GPR_REGISTER_END:
            int reg_idx = addr - GPR_REGISTER_BASE;
            if (reg_idx >= NUM_GPRS)
                return -EINVAL;
            child->thread.gprs[reg_idx] = data;
            break;
        case ACR_REGISTER_BASE ... ACR_REGISTER_END:
            reg_idx = addr - ACR_REGISTER_BASE;
            if (reg_idx >= NUM_ACRS)
                return -EINVAL;
            child->thread.acrs[reg_idx] = data;
            break;
        case FPR_REGISTER_BASE ... FPR_REGISTER_END:
            reg_idx = (addr - FPR_REGISTER_BASE) / sizeof(addr_t);
            if (reg_idx >= NUM_FPRS)
                return -EINVAL;
            child->thread.fprs[reg_idx] = data;
            break;
        default:
            return -EINVAL;
    }
    return 0;
}

int write_task_register_set(struct task_struct *child, addr_t addr, addr_t data) {
    if (!child || (addr & 0x7) != 0)
        return -EINVAL;

    switch (addr) {
        case 0 ... 15:
            child->thread.gpr[addr] = data;
            break;
        case 16 ... 31:
            child->thread.acrs[addr - 16] = data;
            break;
        case 32 ... 63:
            if (addr - 32 >= NR_FPU_REGS)
                return -EINVAL;
            child->thread.fpu_regs[addr - 32].value = data;
            break;
        case 64 ... 67:
            if ((data & 0x3) != 0)
                return -EINVAL;
            child->thread.psw = data;
            break;
        default:
            return -EINVAL;
    }

    return 0;
}
